            else => null,
        },
        .@"and" => switch (role) {
            .@"left" => 1,
            .@"right" => 2,
            else => null,
        },
        .@"or" => switch (role) {
            .@"left" => 1,
            .@"right" => 2,
            else => null,
        },
        .@"neg" => switch (role) {
            .@"operand" => 1,
            else => null,
