            else => null,
        },
        .@"read" => switch (role) {
            .@"operand" => 1,
            else => null,
        },
        .@"write" => switch (role) {
            .@"operand" => 1,
            else => null,
        },
        .@"clone" => switch (role) {
            .@"operand" => 1,
            else => null,
        },
        .@"share" => switch (role) {
            .@"operand" => 1,
            else => null,
        },
        .@"weak" => switch (role) {
            .@"operand" => 1,
            else => null,
        },
        .@"optional" => switch (role) {
            .@"type" => 1,
            else => null,
